func valueCarrierIntelControl(p unsafe.Pointer, c int32) any {
	r := (*carrierintelcontrol.CarrierIntelControl)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		if r.PrimaryProvider == nil {
			return nil
		}
		return string(*r.PrimaryProvider)
	case 4:
		if r.FallbackProvider == nil {
			return nil
		}
		return string(*r.FallbackProvider)
	case 5:
		return string(r.EnrollmentPolicy)
	case 6:
		return int64(r.RecentUsageDays)
	case 7:
		return r.IncludeOpenTenders
	case 8:
		return r.AutoEnrollOnCreate
	case 9:
		return r.AutoUnenrollOnInactive
	case 10:
		return r.ExclusiveWatchlist
	case 11:
		return int64(r.PollIntervalMinutes)
	case 12:
		return int64(r.SnapshotTTLHours)
	case 13:
		return int64(r.FullProfileTTLDays)
	case 14:
		return r.PreTenderRefreshEnabled
	case 15:
		return int64(r.PreTenderMaxAgeHours)
	case 16:
		return int64(r.HardMaxAgeHours)
	case 17:
		return r.ConfirmBlockingChanges
	case 18:
		return string(r.OutagePolicy)
	case 19:
		return r.AutoDisqualifyOnBlock
	case 20:
		return r.AutoApplySafetyRating
	case 21:
		if r.Rules == nil {
			return keel.EmptyJSONObject
		}
		return r.Rules
	case 22:
		if r.AutoSyncFields == nil {
			return keel.EmptyJSONArray
		}
		return r.AutoSyncFields
	case 23:
		if r.MonthlySpendCap == nil {
			return nil
		}
		return *r.MonthlySpendCap
	case 24:
		return int64(r.SoftCapPercent)
	case 25:
		if r.DailyFullProfileCap == nil {
			return nil
		}
		return int64(*r.DailyFullProfileCap)
	case 26:
		return int64(r.RawRetentionDays)
	case 27:
		return int64(r.SnapshotHistoryLimit)
	case 28:
		return r.SelfMonitoringEnabled
	case 29:
		return r.PolicyVersion
	case 30:
		return r.Version
	case 31:
		return r.CreatedAt
	case 32:
		return r.UpdatedAt
	}
	return nil
}

